resource "zpa_application_segment_inspection"
 "this" {  auto_app_protect_enabled = true
  bypass_type              = "NEVER"
  config_space             = "DEFAULT"
  description              = "Issue 687 supported-model verification"
  domain_names = [    "jenkins.example.com",  "jenkins1.example.com"]
  enabled                = true
  health_check_type      = "DEFAULT"
  health_reporting       = "ON_ACCESS"
  icmp_access_type       = "NONE"
  is_cname_enabled       = true
  name                   = "sup4246-inspection-segment"
  passive_health_enabled = true
  segment_group_id       = "<id>"
  tcp_port_range = [
    {      from = "443"
           to   = "443"
    },
    {
      from = "4443"
      to   = "4443"
    },
]
   common_apps_dto {
    apps_config {
      app_types = [        "INSPECT",      ]
      domain               = "jenkins.example.com"
      name                 = "jenkins.example.com"
      trust_untrusted_cert = true
    }
    apps_config {
      app_types = [        "INSPECT",      ]
      domain               = "jenkins1.example.com"
      name                 = "jenkins1.example.com"
      trust_untrusted_cert = true    }
  }
  server_groups {
    id = [      "<id>",    ]
  }
}
